#include "unity.h"
#include "header.h"
#include "helpers.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void setUp(void) { }
void tearDown(void) { }

void unit_test_inorder_non_empty_tree(void) {
    struct node* root = NULL;
    int values[] = {50, 30, 70, 20, 40, 60, 80};
    int size = sizeof(values) / sizeof(values[0]);

    root = helper_build_tree(values, size);
    TEST_ASSERT_NOT_NULL(root);

    // Redirect stdout to a buffer
    char buffer[1024];
    memset(buffer, 0, sizeof(buffer));
    FILE* original_stdout = stdout;
    FILE* stream = fmemopen(buffer, sizeof(buffer), "w");
    TEST_ASSERT_NOT_NULL(stream);
    stdout = stream;

    inorder(root);

    fclose(stream);
    stdout = original_stdout;

    TEST_ASSERT_EQUAL_STRING("20 30 40 50 60 70 80 ", buffer);

    helper_free_tree(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_inorder_non_empty_tree);
    return UNITY_END();
}

